;;
; @file   script_18.asm
; @brief  Hungry traveller on the farm (fAreaEvents_Farm, strcFlags.event4 bit $08): he asks for food, preferably a mushroom
;         (dialogs $032B-$032F); a poisonous mushroom is answered differently. Confidence: medium (derived from the dialogs,
;         flags and callers).
; @bank   $B4   (AI byte code; script id $18, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see    script_17 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_18.asm"
 
; Slot 0: Hungry traveller event.
; Entry code: starts 1 child script (slot $01).
; Slot index: 0
; Started by: fAreaEvents_Farm (A=$0000)
pAIScripting0x18_Farm:
    %AICMD0x09_StartScript($01, pAIScripting0x18_Farm_Actor01)                                   ;B48EE5
    %AICMD0x38_WaitForFadeIn()                                               ;B48EE9
    %AICMD0x10_End()                                           ;B48EEA
pAIScripting0x18_L001:
    %AICMD0x15_JumpIfEquals8(nCurrentTimeID, 18, pAIScripting0x18_Farm_IfCurrentTimeIDIs18)      ;B48EEB
    %AICMD0x13_Wait(1)                                         ;B48EF2
    %AICMD0x12_Jump(pAIScripting0x18_L001)                                   ;B48EF5
pAIScripting0x18_Farm_IfCurrentTimeIDIs18:
    %AICMD0x10_End()                                           ;B48EF8
; Child script (slot $01) of Farm: actor. Spawns at (152,424). Waits for the player to press A. Dialogs $032B, $032F, $032D,
; $032E, $032C.
pAIScripting0x18_Farm_Actor01:
    %AICMD0x15_JumpIfEquals8(nCurrentTimeID, 18, pAIScripting0x18_Farm_Actor01_IfCurrentTimeIDIs18)      ;B48EF9
    %AICMD0x1A_SpawnNpc($0098, $01A8, aAIScriptingData_L082, $01)                     ;B48F00
pAIScripting0x18_L004:
    %AICMD0x2D_JumpOnInteract(pAIScripting0x18_Farm_Actor01_OnInteract, pAIScripting0x18_Farm_Actor01_OnItemOffered)                               ;B48F08
    %AICMD0x16_JumpIfBetween8(nCurrentTimeID, 18, 24, pAIScripting0x18_L011) ;B48F0D
    %AICMD0x12_Jump(pAIScripting0x18_L004)                                   ;B48F15
pAIScripting0x18_L005:
    %AICMD0x2D_JumpOnInteract(pAIScripting0x18_Farm_Actor01_OnInteract_2, pAIScripting0x18_Farm_Actor01_OnItemOffered)                               ;B48F18
    %AICMD0x16_JumpIfBetween8(nCurrentTimeID, 18, 24, pAIScripting0x18_L011) ;B48F1D
    %AICMD0x12_Jump(pAIScripting0x18_L005)                                   ;B48F25
; Handler for A pressed with empty hands.
pAIScripting0x18_Farm_Actor01_OnInteract:
    %AICMD0x1C_ShowDialog($032B, $00)                          ;B48F28
    %AICMD0x12_Jump(pAIScripting0x18_L005)                                   ;B48F2C
; Handler for A pressed while carrying an item.
pAIScripting0x18_Farm_Actor01_OnItemOffered:
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 1, pAIScripting0x18_Farm_Actor01_IfCarryItemIdPrevIs1)              ;B48F2F
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 2, pAIScripting0x18_Farm_Actor01_Say_032E)              ;B48F36
    %AICMD0x1C_ShowDialog($032F, $00)                          ;B48F3D
    %AICMD0x12_Jump(pAIScripting0x18_L004)                                   ;B48F41
pAIScripting0x18_Farm_Actor01_IfCarryItemIdPrevIs1:
    %AICMD0x1B_SetSprite($0309, $01)                                     ;B48F44
    %AICMD0x1C_ShowDialog($032D, $00)                          ;B48F48
    %AICMD0x23_OrWithIndexedValue(strcFlags.event4, $08)       ;B48F4C
    %AICMD0x41_AddValue16(nPlayerHappiness, 20)                ;B48F51
    %AICMD0x12_Jump(pAIScripting0x18_L011)                                   ;B48F57
; Shows dialog $032E.
pAIScripting0x18_Farm_Actor01_Say_032E:
    %AICMD0x1C_ShowDialog($032E, $00)                          ;B48F5A
    %AICMD0x41_AddValue16(nPlayerHappiness, -20)               ;B48F5E
    %AICMD0x12_Jump(pAIScripting0x18_L005)                                   ;B48F64
; Handler for A pressed with empty hands.
pAIScripting0x18_Farm_Actor01_OnInteract_2:
    %AICMD0x1C_ShowDialog($032C, $00)                          ;B48F67
    %AICMD0x12_Jump(pAIScripting0x18_L005)                                   ;B48F6B
pAIScripting0x18_L011:
    %AICMD0x1B_SetSprite($030E, $01)                                     ;B48F6E
    %AICMD0x0D_MoveObject($02, $FE, $04, $01)                             ;B48F72
    %AICMD0x0D_MoveObject($02, $02, $04, $01)                             ;B48F77
    %AICMD0x1B_SetSprite($030E, $01)                                     ;B48F7C
    %AICMD0x0D_MoveObject($01, $00, $48, $01)                             ;B48F80
    %AICMD0x1B_SetSprite($030E, $01)                                     ;B48F85
    %AICMD0x0D_MoveObject($02, $FE, $06, $01)                             ;B48F89
    %AICMD0x0D_MoveObject($02, $02, $04, $01)                             ;B48F8E
    %AICMD0x37_RemoveObject()                                               ;B48F93
pAIScripting0x18_Farm_Actor01_IfCurrentTimeIDIs18:
    %AICMD0x10_End()                                           ;B48F94
